using Dapper;using Valora.Application.Contracts;using Valora.Application.Journey;
namespace Valora.Infrastructure.Repositories;
public sealed class JourneyRepository(IDbConnectionFactory db):IJourneyRepository{const string S="SELECT id,event_type EventType,title,description,source_type SourceType,source_id SourceId,impact_level ImpactLevel,related_dimension RelatedDimension,related_index_code RelatedIndexCode,evidence_summary EvidenceSummary,occurred_at OccurredAt,created_at CreatedAt FROM valorapesquisa.journey_events";public async Task<IReadOnlyList<JourneyEventDto>>Timeline(Guid o,JourneyFilter f,CancellationToken c){using var x=db.Create();return(await x.QueryAsync<JourneyEventDto>(new CommandDefinition(S+" WHERE organization_id=@o AND deleted_at IS NULL AND (@From IS NULL OR occurred_at>=@From) AND (@To IS NULL OR occurred_at<@To) AND (@SourceType IS NULL OR source_type=@SourceType) AND (@RelatedDimension IS NULL OR related_dimension=@RelatedDimension) AND (@RelatedIndexCode IS NULL OR related_index_code=@RelatedIndexCode) AND (@ImpactLevel IS NULL OR impact_level=@ImpactLevel) ORDER BY occurred_at DESC",new{o,f.From,f.To,f.SourceType,f.RelatedDimension,f.RelatedIndexCode,f.ImpactLevel},cancellationToken:c))).ToList();}public async Task<JourneyEventDto?>Get(Guid o,Guid id,CancellationToken c){using var x=db.Create();return await x.QuerySingleOrDefaultAsync<JourneyEventDto>(new CommandDefinition(S+" WHERE organization_id=@o AND id=@id AND deleted_at IS NULL",new{o,id},cancellationToken:c));}public async Task<Guid>Register(Guid o,Guid u,RegisterJourneyEventRequest r,CancellationToken c){var id=Guid.NewGuid();using var x=db.Create();await x.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.journey_events(id,organization_id,diagnostic_id,result_id,governance_cycle_id,event_type,title,description,source_type,source_id,impact_level,related_dimension,related_index_code,evidence_summary,occurred_at,created_by_user_id) VALUES(@id,@o,@DiagnosticId,@ResultId,@GovernanceCycleId,@EventType,@Title,@Description,@SourceType,@SourceId,@ImpactLevel,@RelatedDimension,@RelatedIndexCode,@EvidenceSummary,coalesce(@OccurredAt,now()),@u)",new{id,o,u,r.DiagnosticId,r.ResultId,r.GovernanceCycleId,r.EventType,r.Title,r.Description,r.SourceType,r.SourceId,r.ImpactLevel,r.RelatedDimension,r.RelatedIndexCode,r.EvidenceSummary,r.OccurredAt},cancellationToken:c));return id;}}
